import type { ServerResponse } from "node:http";

import { resource } from "@tinker/core";

import { startServer } from "./modules.server";

export declare namespace Requests {
  /** The Node response a host serves the request on. */
  type Outgoing = ServerResponse;
  /**
   * srvx and h3 read a Node host's response from `request.runtime.node.res`; a host that awaits
   * `beforeEnd` before its last write fails the reply when the request cannot close.
   */
  type Hosted = Request & {
    runtime: { node?: { res: Outgoing }; beforeEnd?: () => Promise<void> };
  };
}

/**
 * Ends each request before its host response ends, as the body read did: `join` closes it
 * gracefully, and a failed close fails the reply. A response that closes first, on a
 * client abort, ends it by force. Scope close destroys the responses still open and fails with
 * any request that could not end and had no reply left to fail.
 */
export const hostResponses = resource({
  label: "start.hostResponses",
  target: "scope",
  factory: (_deps, ctx) => {
    const open = new Map<Requests.Outgoing, Promise<void>>();
    const failures: unknown[] = [];
    const joins = new Map<
      Requests.Outgoing,
      { finish: (graceful: boolean) => Promise<void>; joined?: Promise<void> }
    >();
    ctx.defer(async () => {
      for (const outgoing of open.keys()) outgoing.destroy();
      await Promise.all(open.values());
      if (failures.length) throw failures.at(0);
    });

    return {
      isHosted(request: Request): request is Requests.Hosted {
        return "runtime" in request;
      },
      endOnClose(outgoing: Requests.Outgoing, finish: (graceful: boolean) => Promise<void>) {
        const owned: { finish: typeof finish; joined?: Promise<void> } = { finish };
        joins.set(outgoing, owned);
        const closed = outgoing.closed
          ? Promise.resolve()
          : new Promise<void>((resolve) => outgoing.once("close", resolve));
        const ending = closed
          .then(() =>
            owned.joined ? owned.joined.catch(() => {}) : finish(outgoing.writableFinished),
          )
          .then(
            () => {
              open.delete(outgoing);
              joins.delete(outgoing);
            },
            (error: unknown) => {
              open.delete(outgoing);
              joins.delete(outgoing);
              failures.push(error);
            },
          );
        open.set(outgoing, ending);
      },
      /** The host awaits this before its last write; a failed close fails the reply. */
      join(outgoing: Requests.Outgoing): Promise<void> {
        const owned = joins.get(outgoing);
        if (owned === undefined) return Promise.resolve();

        return (owned.joined ??= owned.finish(true));
      },
    };
  },
});

/** Retains request work until the consumer ends, fails, or cancels the body. */
export const responseBodies = resource({
  label: "start.responseBodies",
  target: "scope",
  depends: { startServer },
  factory: async ({ startServer }, ctx) => {
    const readers = new Set<{
      reader: ReadableStreamDefaultReader<Uint8Array>;
      finish: (graceful: boolean) => Promise<void>;
      cancelled: boolean;
    }>();
    ctx.defer(async () => {
      const results = await Promise.allSettled(
        [...readers].map(async (owned) => {
          owned.cancelled = true;
          readers.delete(owned);
          const ended = await Promise.allSettled([owned.reader.cancel(), owned.finish(false)]);
          for (const result of ended) if (result.status === "rejected") throw result.reason;
        }),
      );
      for (const result of results) if (result.status === "rejected") throw result.reason;
    });
    return {
      isResponse(value: unknown): value is Response {
        return value instanceof Response;
      },
      hold(
        response: Response,
        finish: (graceful: boolean) => Promise<void>,
      ): Response | Promise<Response> {
        if (response.body === null) {
          return finish(true).then(() => response);
        }

        const reader = response.body.getReader();
        const owned = { reader, finish, cancelled: false };
        readers.add(owned);

        const body = new ReadableStream<Uint8Array>({
          async pull(controller) {
            try {
              const part = await reader.read();
              if (part.done) {
                readers.delete(owned);
                await finish(!owned.cancelled);
                if (!owned.cancelled) controller.close();
              } else if (!owned.cancelled) controller.enqueue(part.value);
            } catch (error) {
              readers.delete(owned);
              await finish(false);
              if (!owned.cancelled) controller.error(error);
            }
          },
          async cancel(reason) {
            owned.cancelled = true;
            readers.delete(owned);
            const results = await Promise.allSettled([finish(false), reader.cancel(reason)]);
            for (const result of results) {
              if (result.status === "rejected") throw result.reason;
            }
          },
        });

        return startServer.transferResponseBodyOwnership(
          response,
          new Response(body, {
            status: response.status,
            statusText: response.statusText,
            headers: response.headers,
          }),
        );
      },
    };
  },
});

import { tag } from "@tinker/core";

/** Only request wiring and auth borrow the raw headers; app operations use principal. */
export const requestHeaders = tag<Headers>({ label: "request.headers" });

export { startRequests, backendStop, requestStop } from "./index";
export { readResult } from "./result.server";
export { requestHeaders } from "./headers.server";
export { requestBody } from "./request-body.server";
export { responseBodies } from "./body.server";
export { renderFrames } from "./render-lifetime.server";

import { resource, tag } from "@tinker/core";
import type { Scope } from "@tinker/core";

import { hostResponses } from "./body.server";
import { renderFrames } from "./render-lifetime.server";

/** The native middleware lends its session close to that session. */
export const requestClose = tag<(graceful: boolean) => Promise<Scope.Result>>({
  label: "request.closeOwner",
});

/**
 * One session resource per request: it shares one close promise without joining the
 * session's own teardown, and retains the request's render close until that teardown.
 */
export const requestLifetime = resource({
  label: "request.close",
  target: "session",
  depends: { close: requestClose.required, renders: renderFrames, responses: hostResponses },
  factory: ({ close, renders, responses }, ctx) => {
    let closed: Promise<void> | undefined;
    let owned: { close: (() => Promise<void>) | undefined } | undefined;
    let request: Request | undefined;
    ctx.defer(() => {
      if (request) renders.release(request);
      request = undefined;
      const render = owned?.close;
      if (owned) owned.close = undefined;
      return render?.();
    });

    const lifetime = {
      finish: (graceful: boolean) => {
        return (closed ??= Promise.resolve(close(graceful)).then((end) => {
          if (end.teardownErrors?.length) throw end.teardownErrors.at(0);
        }));
      },
      open(value: Request) {
        request = value;
        owned = renders.open(value);
      },
      /**
       * The host ends the request before its response ends, with no body rewrap: it awaits the
       * lent `beforeEnd`, or its response close ends the request. False without a host.
       */
      endOnHostClose(hosted: Request) {
        if (!responses.isHosted(hosted) || hosted.runtime.node === undefined) return false;

        const outgoing = hosted.runtime.node.res;
        responses.endOnClose(outgoing, lifetime.finish);
        hosted.runtime.beforeEnd = responses.join.bind(undefined, outgoing);
        return true;
      },
    };
    return lifetime;
  },
});

import { tag } from "@tinker/core";

/** The main supplies its host signal before graceful drain joins held requests. */
export const backendStop = tag<AbortSignal>({ label: "lifetime.backendStop" });

export const requestStop = tag<AbortSignal>({ label: "lifetime.requestStop" });

import { resource } from "@tinker/core";

export const startServer = resource({
  label: "module:@tanstack/react-start/server",
  target: "scope",
  factory: () => import("@tanstack/react-start/server"),
});

import { resource } from "@tinker/core";

import { raise } from "~/components/errors";

/** The app owns the lookup; each request session owns its render close (`requestLifetime`). */
export const renderFrames = resource({
  label: "request.renders",
  target: "scope",
  factory: () => {
    const renders = new WeakMap<Request, { close: (() => Promise<void>) | undefined }>();

    return {
      open(request: Request) {
        const owned = { close: undefined as (() => Promise<void>) | undefined };
        renders.set(request, owned);
        return owned;
      },
      release(request: Request) {
        renders.delete(request);
      },
      retain(request: Request, close: () => Promise<void>) {
        const owned = renders.get(request);
        if (owned === undefined) raise("StartScopeMissing", {});
        owned.close = close;
      },
    };
  },
});

import { resource } from "@tinker/core";

import { backendStop, requestStop } from "./lifetime";

/** The request owns the reader; its route borrows it until all body checks finish. */
export const requestBody = resource({
  label: "request.body",
  target: "session",
  depends: { backendStop, requestStop },
  factory: ({ backendStop, requestStop }, ctx) => {
    const signal = AbortSignal.any([backendStop, requestStop, ctx.signal]);
    let reader: ReadableStreamDefaultReader<Uint8Array<ArrayBuffer>> | undefined;
    let cancellation: Promise<void> | undefined;

    const cancel = () => {
      cancellation ??= reader?.cancel();
    };
    signal.addEventListener("abort", cancel, { once: true });

    const release = async () => {
      signal.removeEventListener("abort", cancel);
      if (signal.aborted) cancel();
      await cancellation;
      reader?.releaseLock();
      reader = undefined;
    };
    ctx.defer(release);

    return {
      signal,
      open(body: ReadableStream<Uint8Array<ArrayBuffer>>) {
        reader = body.getReader();
        if (signal.aborted) cancel();
        return reader;
      },
      release,
    };
  },
});

import type { RunResult } from "@tinker/core";

import { fail } from "~/components/errors";

/** HTTP boundaries handle a settled failure without failing the server root.
 * @param result - From a settled boundary call; why: return its value or raise its failure.
 */
export function readResult<T>(result: RunResult<T>): T {
  if (result.status === "failed") throw result.error;
  if (result.status === "cancelled") throw fail("Cancelled", {});
  return result.value;
}

import { createMiddleware } from "@tanstack/react-start";
import { extension } from "@tinker/core";
import type { Scope } from "@tinker/core";

import { raise } from "~/components/errors";

import { responseBodies } from "./body.server";
import { requestHeaders } from "./headers.server";
import { backendStop, requestStop } from "./lifetime";
import { requestClose, requestLifetime } from "./lifetime.server";

/** Start merges this registry to type the context supplied by the server entry. */
declare module "@tanstack/react-start" {
  interface Register {
    server: { requestContext: { scope?: Scope.Handle } };
  }
}

/** This root middleware uses only fetch context, before global middleware has run. */
const middleware = createMiddleware().server(async ({ context, request, next }) => {
  if ("session" in context && context.session !== undefined) raise("StartSessionAlreadySet", {});

  const scope = context.scope;
  if (scope === undefined) raise("StartScopeMissing", {});

  const session = scope.createSession({
    tags: [
      requestHeaders(request.headers),
      requestStop(request.signal),
      requestClose((graceful) => session.close({ graceful })),
    ],
  });
  const lifetime = session.resolve(requestLifetime);
  lifetime.open(request);

  try {
    const result = await next({ context: { session, signal: request.signal } });
    if (lifetime.endOnHostClose(request)) return result;

    return {
      ...result,
      response: await (
        await session.resolve(responseBodies)
      ).hold(result.response, lifetime.finish),
    };
  } catch (error) {
    await lifetime.finish(false);
    throw error;
  }
});

/** Startup supplies the root context; all Start boundaries share this middleware. */
export const startRequests = Object.assign(
  extension({
    label: "start.requests",
    hooks: {
      async start(event) {
        event.resolve(backendStop);
        await event.next();
        return { scope: event.scope };
      },
    },
  }),
  { middleware },
);
